import pytest
from starlette.testclient import TestClient
from markitdown_mcp.__main__ import create_starlette_app
from unittest.mock import AsyncMock, MagicMock
from starlette.requests import Request
from starlette.routing import Route, Mount
from starlette.applications import Starlette

@pytest.fixture
def mock_server():
    server = MagicMock()
    server.run = AsyncMock()
    server.create_initialization_options = MagicMock(return_value={})
    return server

@pytest.fixture
def app(mock_server):
    return create_starlette_app(mock_server, debug=True)

@pytest.fixture
def test_client(app):
    return TestClient(app)

def test_create_starlette_app_routes(app):
    assert isinstance(app, Starlette)
    routes = app.routes
    assert len(routes) == 3
    assert isinstance(routes[0], Route)
    assert routes[0].path == "/sse"
    assert isinstance(routes[1], Mount)
    assert routes[1].path == "/mcp"
    assert isinstance(routes[2], Mount)
    assert routes[2].path == "/messages/"

def test_sse_endpoint(test_client, mock_server):
    response = test_client.get("/sse")
    assert response.status_code == 200
    mock_server.run.assert_called_once()

def test_streamable_http_endpoint(test_client):
    response = test_client.get("/mcp")
    assert response.status_code == 404  # No specific handler for GET requests

def test_messages_endpoint(test_client):
    response = test_client.post("/messages/")
    assert response.status_code == 404  # No specific handler for POST requests

def test_lifespan(app, mock_server):
    with TestClient(app) as client:
        assert client.app.lifespan is not None
        mock_server.run.assert_not_called()

